"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52982"],{76774(e){e.exports=JSON.parse('{"id":"FIN-1419","slug":"directors-and-officers-insurance","term":"Directors and Officers Insurance (D&O)","also_known_as":["D&O"],"difficulty":"Advanced","definition":"Directors and officers insurance (D&O) is liability insurance that protects company directors and senior officers against the personal costs of claims alleging wrongful acts in their management of the company, such as breaches of duty, misleading statements or mismanagement.","explanation":["Directors and officers can be personally sued by shareholders, regulators, employees, creditors or competitors. Legal costs alone can be very high, even if they are eventually cleared. D&O insurance pays for defence costs, settlements and damages, within policy limits and exclusions.","Policies commonly have several parts: cover for individual directors when the company cannot indemnify them, cover that reimburses the company when it indemnifies its directors, and, for listed companies, cover for the company itself against securities claims.","For example, after a company\'s share price falls sharply following an accounting problem, shareholders might sue its directors for misleading statements. D&O insurance would cover the directors\' legal costs and any settlement.","D&O insurance helps companies attract qualified directors, who might otherwise be unwilling to take on personal risk. Exclusions typically include fraud, deliberate criminal acts and illegal personal profits, usually once proven. Premiums rise for companies in higher-risk situations, such as initial public offerings or financial distress."],"note":"","total":1725,"prev":{"slug":"direct-listing","term":"Direct Listing"},"next":{"slug":"dirty-price","term":"Dirty Price"}}')}}]);